                if (q.trim().length < 2) { fres.innerHTML = '<div style="opacity:.7;font-size:12px;padding:4px">Gõ ít nhất 2 chữ. Tìm được: tên mục (tab), vật phẩm, quái vật, địa danh, sự kiện, và chữ trong các mục đã mở ở lần này.</div>'; return; }
                if (!ds.length) { fres.innerHTML = '<div style="opacity:.7;padding:4px">Không thấy gì khớp.</div>'; return; }
