                [win, toastEl].forEach(function (el) { el.style.setProperty('--vkx-k', String(k)); });
                win.classList.remove('vkx-m'); win.classList.remove('vkx-t'); win.classList.remove('vkx-land');
                win.classList.toggle('vkx-xs', effW < 370);
