    const voSac = manh.map((p) => { const it = B.items.get(p.m.item), h = ((it && it.he) || []).filter(Boolean); return h.length > 0 && h.every((x) => x === 'vo_sac'); });   // thu.1: món chỉ có hệ vô sắc
