    for (let h = 0; h < q.length && end < 0; h++) { const x = q[h]; if (goal.has(x)) { end = x; break; } for (const o of Dx.nb[x]) if (free(o) && !prev.has(o)) { prev.set(o, x); q.push(o); } }
