      const thC = kmDThongCells(Dx, St), cx = (cn) => { let sx = 0, sy = 0; for (const x of cn.cells) { sx += x % Dx.g.rong; sy += Math.floor(x / Dx.g.rong); } return [sx / cn.cells.length, sy / cn.cells.length]; }, c0 = cx(d);
