          + '#vkx-win:not(.vkx-wide) #vkx-cn,#vkx-win:not(.vkx-wide) #vkx-help,#vkx-win:not(.vkx-wide) #vkx-tach{display:none}#vkx-win.vkx-wide #vkx-more,#vkx-win.vkx-wide #vkx-mnu{display:none!important}'
