    abb: [/^Auto /, /^Tiến Trình/, /^Nhật Ký/], asy: [/^Auto /, /^Tiến Trình/, /^Nhật Ký/], arr: [/^Auto /, /^Tiến Trình/, /^Nhật Ký/],
    atd: [/^Tìm Đồ/, /^Săn Đồ/],
    aus: [/^Auto Sự Kiện/, /^Tùy chọn/, /^Sự kiện bỏ qua/, /^Nhật ký/],
    adg: [/^Auto Đấu Giá/, /^Tiến Trình/, /^Nhật Ký/, /^Nhà Đấu Giá/, /^Thế Cục/],
