  let prioQueued = false;
  const prioObs = new MutationObserver(() => {
    if (prioBusy || prioQueued) return;
    prioQueued = true;
    Promise.resolve().then(() => { prioQueued = false; prioritizeCards(); });
  });
  prioObs.observe(body, { childList: true });

  // ═════ 8.9.2-thu.11: KHUNG MẸO Ở ĐẦU MỖI TAB ═════
  // "Cách làm · Cần biết · Mẹo" ngắn theo đúng chức năng hiện có của tab. Lần đầu mở một tab thì xổ ra, các lần sau thu gọn; bấm tiêu đề để mở / đóng và Tool nhớ theo tab (localStorage). Tắt hết ở Hệ Thống.
  const VKX_MEO = {
    akm: {
      lam: ['Chọn hướng build, Chế Độ và Độ Kỹ ở thẻ Cài Đặt Chung; muốn dồn sức cho món nào thì ghim ở Món muốn có (Chủ Đạo).', 'Bấm Xếp Từ Túi để xem thử, ưng thì Áp Dụng Vào Game; muốn Tool tự làm và tự xếp lại khi có đồ mới thì dùng Auto Kinh Mạch.', 'Ưu tiên bộ: chọn một bộ món, tick Xếp đủ bộ để ép mọi món đang có của bộ vào lưới.'],
      biet: ['Không cho nghịch: luôn tìm cách 0 điểm nghịch trước, tắt thì cho đánh đổi nghịch lấy sức mạnh. Lấp đầy ô: bước cuối nhét thêm món vào ô trống nếu điểm gần như không giảm.', 'Ưu tiên đủ bộ: thưởng thêm theo mốc bộ đạt. Không dùng dị bảo: bỏ món dị bảo, trừ món đã ghim.', 'Món mới đặt chỉ mạnh ×0,5 tới khi Lĩnh Ngộ đủ nên Tool chỉ đổi khi điểm tăng đủ lớn.'],
      meo: ['Thuật toán Mới chấm theo mốc bộ đang xếp: Cân Bằng = 70% đánh nhau + 20% tu luyện + 10% đột phá; Tu Luyện = 65% tu luyện + 10% đột phá + 25% đánh nhau. Hướng xếp (Sinh / Khắc) chỉ phá hòa vì game đã tính sinh khắc vào sức mạnh.', 'Kết quả đánh thử có Thắng · Hòa · Thua; Hòa là hết 30 hiệp mà chưa ai ngã. Dòng Linh lực cho biết chiêu tốn và hồi mỗi lượt: hồi thấp hơn tốn thì bộ dễ cạn linh lực giữa trận.', 'Bảng Chấm Các Bộ Đã Lưu so các bộ kinh mạch bạn đang có (cột Thắng · Hòa, hồi / tiêu).'],
    },
    abb: {
      lam: ['Chọn vốn, lãi tối thiểu, số năm đường rồi bấm Xem Kế Hoạch (Không Đi) để xem các chuyến trước khi chạy Auto.'],
      biet: ['Tự nộp lệ phí vào thành / tông (mặc định bật, trần 200 linh thạch mỗi lần): gặp cổng thu phí thì Auto nộp phí lượt rồi vào, không bao giờ tự mua lệnh bài. Tắt hoặc phí vượt trần thì Auto dừng và báo lý do.', 'Lãi mỗi chuyến đã trừ lệ phí vào nơi mua và nơi bán nếu còn bị chặn.'],
      meo: ['Nộp phí nhiều lần ở cùng một nước thì Tool nhắc khi đã bằng nửa giá lệnh bài: tự mua trong game nếu đi lại thường xuyên.'],
    },
    adg: {
      lam: ['Chọn nhà đấu giá và các món cần, đặt giá tối đa rồi bấm Chạy Tự Động.'],
      biet: ['Tự nộp lệ phí vào thành / tông cũng áp dụng khi đi tới nhà đấu giá hoặc đại hội ở nơi thu phí (mặc định bật, trần 200 linh thạch; phần linh thạch giữ lại tối thiểu vẫn được chừa).'],
      meo: ['Cổng thu phí quá trần thì Auto dừng báo; tăng trần hoặc tự vào trong game.'],
    },
    aap: {
      lam: ['Chọn liệu chính (chỉ liệu đang có trong túi), điều kiện dừng rồi bấm Chạy Tự Động.'],
      biet: ['Auto ấp trứng bằng lệnh game, bế quan chờ nghi thức xong, con ra thì chấm điều kiện: đạt thì dừng, không đạt thì giữ con và ấp tiếp tới hết số trứng tối đa. Trứng quý chỉ ấp khi tick "Dùng cả trứng quý". Không thả con, không mua trứng.'],
      meo: ['Mỗi lần ấp tốn trứng và linh thạch thật; Tool không tua lại kết quả.'],
    },
    cho: {
      lam: ['Xem Đồ đáng mua bằng linh thạch và Bộ mua tốt nhất với số linh thạch hiện có; Toàn bộ hàng theo nơi để tra từng điểm bán.'],
      biet: ['Dữ liệu là hàng tiệm ở nơi bạn đang đứng; đổi nơi thì danh sách đổi theo.', 'Mục Đan cho lần đột phá tới và Dụng cụ nghề giúp mua đúng thứ sắp cần.'],
      meo: ['Mua xong bấm Làm mới để Tool tính lại theo số linh thạch còn lại.'],
    },
    lpk: {
      lam: ['Xem Phái Của Bạn: phái nào chiếm đủ tỉ lệ ô thông trên kinh mạch thì thành đạo thống chiến đấu.', 'Đọc Khuyến Cáo Cho Bạn rồi tra Các Phái Và Ảnh Hưởng để biết món nào thuộc phái nào.'],
      biet: ['Đạo thống ảnh hưởng thiện cảm ban đầu với từng phe. Có thể có thêm đạo thống nghề khi nghề đạt bậc ba.'],
      meo: ['Muốn đổi phái chính: đổi món trên kinh mạch (Auto Build) rồi xem lại tab này.'],
    },
    dp: {
      lam: ['Xem Lên cảnh giới kế: điều kiện còn thiếu, các phương án (đan trong túi + đốt thọ) và chi tiết phương án tốt nhất.', 'Mục Tự Phá Bình Cảnh dùng khi đang đứng ải (tu vi chỉ thấm 1/10 tới khi phá).'],
      biet: ['Phẩm đạo cơ và Tâm ma, Nghiệp ảnh hưởng tỉ lệ đột phá đại cảnh giới.', 'Tỉ lệ có trần do game đặt; vượt trần thì thêm đan cũng không tăng.', 'Đang ở ải bình cảnh: tu vi mọi nguồn chỉ thấm 1/10 (bản 0.3.1a); phá ải bằng sự kiện cơ duyên, chuỗi kỳ ngộ, mini game, đan (~nửa ải) hoặc yêu tài (~1/4).'],
      meo: ['Bộ kinh mạch Đột Phá (Auto Build, Số Bộ = Nhiều Bộ) giúp tăng tỉ lệ trước khi bấm đột phá.'],
    },
    tcv: {
      lam: ['Gõ tên món (không cần dấu) hoặc chọn nhóm, cảnh giới, hệ, phẩm, công dụng ở Bộ Lọc Nâng Cao.', 'Ô Tình trạng: Đang có / Còn thiếu / Đã gặp / Chưa gặp (đang có tính cả túi, kinh mạch, trang bị, bản mệnh).'],
      biet: ['“Đã gặp” là Tool tự ghi lại món đã vào túi hay từng thấy; lưu trên máy, chung mọi kiếp, không ghi vào save.', 'Bấm vào món để xem chi tiết, nguồn có được và thẻ vật phẩm của game.'],
      meo: ['Tìm Cả Trong Mô Tả để dò theo công dụng; Chỉ Mục Của Mod hiện khi có mod khác thêm món.'],
    },
    tbm: {
      lam: ['Tra từng bộ món: bộ có những món nào, bạn đang có bao nhiêu và bộ cho chiêu hay buff gì.'],
      biet: ['Đủ món mới kích hoạt các mốc của bộ.'],
      meo: ['Chọn bộ muốn theo ở đây rồi sang Auto Build đặt làm Ưu tiên bộ.'],
    },
    db: {
      lam: ['Xem dị bảo nào đã nhận, đang có trên bản đồ, chờ hồi chiêu hay chưa đủ cảnh giới; có nút đi tới địa điểm.', 'Ô Tình trạng lọc Đang có / Còn thiếu / Đã gặp / Chưa gặp.'],
      biet: ['Dị bảo chỉ hiện trên bản đồ khi game cho sự kiện xuất hiện và tan sau vài năm; đủ điều kiện chưa chắc đã thấy.', 'Mục dị bảo ngẫu nhiên không có món cố định nên không lọc theo Tình trạng được.'],
      meo: ['Không muốn Auto Build dùng dị bảo: tick Không dùng dị bảo ở tab Auto Build.'],
    },
    hts: {
      lam: ['Thẻ Cập nhật: xem bản đang chạy và bản mới. Tự kiểm tra: soát Tool có đọc được game không.', 'Thẻ Chuyển Máy: xuất / nhập cài đặt Tool sang máy khác.'],
      biet: ['Mọi Auto mặc định tắt. Mục Mod Khác Đang Chạy báo mod có thể xung đột với Tool.'],
      meo: ['Gặp lỗi: cập nhật bản mới, vẫn lỗi thì vào Báo Lỗi.'],
    },
  };
  const MEO_LK = 'vkx_meo_st';
  const meoDoc = () => { try { const o = JSON.parse(localStorage.getItem(MEO_LK) || '{}'); return o && typeof o === 'object' ? o : {}; } catch (e) { return {}; } };
  const meoGhi = (o) => { try { localStorage.setItem(MEO_LK, JSON.stringify(o)); } catch (e) { /* bỏ qua */ } };
  const meoBat = () => { try { return localStorage.getItem('vkx_meo_on') !== '0'; } catch (e) { return true; } };
  const MEO_FIRST = new Set();   // tab mở lần đầu trong lượt chạy này: giữ mở cho tới khi người dùng đóng
  function meoVe() {
    try {
      const old = body.querySelector(':scope > .vkx-meo'), k = S.tab, M = VKX_MEO[k];
      if (!M || !meoBat() || body.querySelector('#vk-pg') || !body.firstElementChild) { if (old && (!M || !meoBat())) old.remove(); return; }
      if (old && old.dataset.meo === k) return;
      if (old) old.remove();
      const d = meoDoc(); d.seen = d.seen || {}; d.open = d.open || {};
      if (!d.seen[k]) { d.seen[k] = 1; MEO_FIRST.add(k); meoGhi(d); }
      const mo = d.open[k] !== undefined ? !!d.open[k] : MEO_FIRST.has(k);
      const ul = (a) => '<ul style="margin:2px 0 6px;padding-left:18px">' + a.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>';
      const el = document.createElement('details'); el.className = 'vkx-meo'; el.dataset.meo = k; if (mo) el.open = true;
      el.style.cssText = 'margin:0 0 8px;padding:6px 10px;border:1px dashed var(--line);border-radius:12px;background:var(--bg2);font-size:12.5px;line-height:1.5';
      el.innerHTML = '<summary style="cursor:pointer;font-weight:600;color:var(--acc2)">💡 Cách làm · Cần biết · Mẹo</summary><div><b>Cách làm</b>' + ul(M.lam) + '<b>Cần biết</b>' + ul(M.biet) + '<b>Mẹo</b>' + ul(M.meo) + '</div>';
      let cur = mo; el.addEventListener('toggle', () => { if (el.open === cur) return; cur = el.open; const o = meoDoc(); o.open = o.open || {}; o.open[k] = el.open; meoGhi(o); MEO_FIRST.delete(k); });
      body.insertBefore(el, body.firstElementChild);
    } catch (e) { /* bỏ qua */ }
  }
  new MutationObserver(() => { Promise.resolve().then(meoVe); }).observe(body, { childList: true });

  async function renderCore() {
    if (S.tab === 'km' || S.tab === 'bld') S.tab = 'akm'; // hai tab cũ đã gộp vào Auto Build
    drawTabs();
    body.onclick = null;
    try {
      if (S.tab === 'tcv' || S.tab === 'tcq') { S.abort = false; (S.tab === 'tcv' ? tabVatPham : tabQuaiVat)(); return; }
      if (S.tab === 'arr') { S.abort = false; tabAutoReroll(); return; }
      if (S.tab === 'lhs') { S.abort = false; tabLuanHoi(); return; } // Luân Hồi chạy được cả khi chưa vào kiếp nào
      if (S.tab === 'lht') { S.abort = false; tabThanhTuu(); return; } // Auto Reroll Tư Chất chạy được cả khi chưa vào kiếp nào
      if (!S.core) {
        const myTab = S.tab;
        body.innerHTML = `<div class="vk-card">⏳ <span id="vk-pg">Đang chuẩn bị…</span></div>`;
        // chỉ nạp code game MỘT lần dù người dùng bấm tab/làm mới liên tục trong lúc chờ (trước đây mỗi lần bấm nạp thêm một bản → nặng, đứng hình)
        if (!S.coreP) S.coreP = loadCore((m) => { const el = body.querySelector('#vk-pg'); if (el) el.textContent = m; }).then((k) => { S.core = k; return k; }, (e) => { S.coreP = null; throw e; });
        const wd = setTimeout(() => { const el = body.querySelector('#vk-pg'); if (el && !S.core) el.parentElement.insertAdjacentHTML('beforeend', '<div class="vk-mu" style="font-size:12px;margin-top:6px">Đang lâu hơn bình thường. Nếu quá 30 giây, bấm ↻ để thử lại.</div>'); }, 15000);
        try { await S.coreP; } finally { clearTimeout(wd); }
        if (S.tab !== myTab) return; // người dùng đã chuyển tab trong lúc chờ: lượt render của tab mới lo phần còn lại
      }
      if (!G().state.run) { body.innerHTML = `<div class="vk-card">Chưa có kiếp nào đang chơi. Vào game (tạo hoặc nạp kiếp) rồi bấm <b>Làm mới</b>.</div>`; return; }
      S.abort = false; if (S.core && S.core.sync) S.core.sync();
      clearTimeout(S.skxT); // 8.4.2-thu.3: dựng ngầm chỉ mục sự kiện chỉ khi người dùng đứng yên ~5 s (mỗi lần dựng tab lại tính từ đầu) và luồng rảnh, mỗi lô ≤ 40 ms
      if (S.tab !== 'tce' && !(S.skx && S.skx.src === C()) && !S.skxP) S.skxT = setTimeout(() => { try { const chay = () => { try { if (G().state.run) skIndexLo(); } catch (e) { /* bỏ qua */ } }; if (typeof requestIdleCallback === 'function') requestIdleCallback(chay, { timeout: 5000 }); else chay(); } catch (e) { /* bỏ qua */ } }, 5000);
      ({ tq: () => { tabTongQuan(); tongQuanExtra(); }, dp: tabDotPha2, tr: tabTran, tkc: tabTKC, bm: tabBanMenh, cho: tabCho, ld: tabLuyenDan, cph: tabCheePhu, lbo: tabLuyenBao, tph: tabTranPhap, tien: tabTien, bd: tabBanDo, tt: tabTreoThuong, san: tabSan, tcv: tabVatPham, tcq: tabQuaiVat, tcd: tabDiaDanh, db: tabDiBao, tce: tabSuKien, nlw: tabNLW, nlm: tabNLM, nls: tabNLS, nlv: tabNLV, nlc: tabNLC, lhd: tabDuTinhDiem, tkb: tabThienKieu, nmn: tabNhanMach, abb: tabAutoBuon, asy: tabAutoSan, akm: tabAutoKm, arr: tabAutoReroll, atd: tabTimSanDo, adg: tabAutoDauGia, aap: tabAutoApTrung, tbm: tabBoMon, tkh: tabKeHoachDi, lpk: tabLuuPhai, tcn: tabTheChat, syt: tabSanYeu, hth: tabHaiThuoc, hts: tabHeThong, aus: tabAutoSuKien, bl: tabBaoLoi })[S.tab]();
      timChup(S.tab);
    } catch (e) {
      console.error(e); body.innerHTML = errBox(e) + '<button class="vk-btn sec" id="vk-retry">↻ Thử Lại</button><div class="vk-card" id="vk-ds" style="margin-top:10px"></div>';
      const rb = body.querySelector('#vk-retry'); if (rb) rb.onclick = () => { S.core = null; S.coreP = null; render(); };
      // Lõi hỏng sau khi game cập nhật vẫn xuất được báo cáo dữ liệu (không cần lõi): gửi Claude.
      try { dsMount(body.querySelector('#vk-ds')); } catch (e2) { console.error('[ds] mount', e2); }
    }
  }
  // 7.16.0-thu.4: đo thời gian dựng tab (kể cả chờ nạp lõi lần đầu); chậm quá 300 ms thì ghi console.debug để gửi khi còn lag.
  // 7.17.4-thu.7: nhớ vị trí cuộn từng tab (RAM + sessionStorage); đổi tab / Làm mới xong thì trả về chỗ cũ.
  const SCROLL = (() => { try { return JSON.parse(sessionStorage.getItem('vkx_scroll') || '{}') || {}; } catch (e) { return {}; } })();
  function scrollLuu() { try { sessionStorage.setItem('vkx_scroll', JSON.stringify(SCROLL)); } catch (e) { /* bỏ qua */ } }
  async function render() {
    S.gen++; if (S.choRender) { try { cancelAnimationFrame(S.choRender); } catch (e) { /* bỏ qua */ } S.choRender = 0; }
    const t0 = performance.now(), cur = S.tab;
    if (S.scTab && body.scrollHeight > 0) { SCROLL[S.scTab] = body.scrollTop; scrollLuu(); }
    S.scTab = cur;
    try { return await renderCore(); } finally {
      auBarVe();
      const y = SCROLL[cur] || 0;
      if (y > 0) requestAnimationFrame(() => requestAnimationFrame(() => { try { if (S.tab === cur) body.scrollTop = y; } catch (e) { /* bỏ qua */ } })); try { const ms = Math.round(performance.now() - t0); if (ms > 50) console.info('[VKX] dựng', S.tab, ms + ' ms'); } catch (e) { /* bỏ qua */ } } }

  const progressHtml = (id) => `<div id="${id}" style="display:none"><div class="vk-bar"><i></i></div><div class="vk-mu" style="font-size:13px"></div><button class="vk-btn sec vk-stop">Dừng</button></div>`;
  function bindProgress(box) {
    box.style.display = 'block';
    box.querySelector('.vk-stop').onclick = () => { S.abort = true; };
    const t0 = Date.now();   // 7.17.4-thu.4: "còn ~Ns" ước theo thời gian đã chạy / phần đã xong (chỉ ước lượng, các pha có ngân sách giờ riêng)
    return (f, label) => { const el = Date.now() - t0; let eta = ''; if (f >= 0.96 && f < 0.995) { eta = ' · đã chạy ' + Math.round(el / 1000) + ' giây'; } else if (f >= 0.05 && f < 0.995 && el > 3000) { const n = Math.round(el * (1 - f) / f / 1000); eta = ' · còn ~' + (n >= 90 ? Math.round(n / 60) + ' phút' : n + ' giây'); } box.querySelector('i').style.width = Math.round(f * 100) + '%'; box.querySelector('.vk-mu').textContent = (label || '') + ' ' + Math.round(f * 100) + '%' + eta; };
  }

  // cơ duyên còn hạn: lấy từ run.nodes (nguồn thật, mất khi đã xong); bổ sung tin việc có hạn không gắn nơi nào còn sự kiện
  function coDuyenConHan(c) {
    const run = c.run, Cc = C(), out = [], daCo = new Set();
    for (const [slot, n] of Object.entries(run.nodes || {})) {
      if (!n || !n.encounter || n.hetHanNam === undefined || n.hetHanNam <= run.nam) continue;
      const def = Cc.encounters.get(n.encounter);
      out.push({ slot, ten: `${cleanTxt((def && def.ten) || n.encounter)} · ${placeName(c, slot)}`, left: n.hetHanNam - run.nam });
      daCo.add(slot);
    }
    // 7.17.3-thu.1: bí cảnh là nơi chốn (không nằm trong run.nodes): hỏi thẳng game xem đang khai mở không
    const biCanh = new Set();
    try {
      const noi = TT.core && TT.core['world/noi'];
      if (noi && typeof noi.secretRealmWindow === 'function') {
        const env = G().env, W = c.world || env.world;
        for (const s of (W.slots || [])) {
          if (!s || !s.dia_danh || s.an) continue;
          let dd = null; try { dd = W.diaDanh(s.dia_danh); } catch (e) {}
          if (!dd || dd.loai !== 'bi_canh' || dd.an) continue;
          biCanh.add(s.id);
          let w = null; try { w = noi.secretRealmWindow(env, run, s.id); } catch (e) {}
          if (!w || !w.open) continue;
          const nc = run.noiChon && run.noiChon[s.id];
          if (nc && nc.enteredCycle !== undefined && nc.enteredCycle === w.cycle) continue; // đã vào kỳ này
          const left = w.closesAt - run.nam; if (!(left > 0)) continue;
          let cg = ''; try { cg = noi.realmWindowText(noi.realmTypeWindow(noi.secretRealmType(env, run, s.id))); } catch (e) {}
          out.push({ slot: s.id, ten: `Bí cảnh ${cleanTxt(dd.ten)} khai mở${cg ? ' (vào được: ' + cleanTxt(cg) + ')' : ''}`, left });
          daCo.add(s.id);
        }
      }
    } catch (e) { /* bỏ qua */ }
    const seen = new Map();
    for (const l of run.log || []) if (l.expiresAt && l.key) seen.set(l.key, l);
    for (const l of seen.values()) {
      if (l.slot && (daCo.has(l.slot) || biCanh.has(l.slot))) continue;
      out.push({ slot: l.slot, ten: cleanTxt(String(l.text).replace(/còn [\d.,]+ năm\.?/, '').replace(/[,\s]+$/, '')), left: l.expiresAt - run.nam });
    }
    return out.sort((a, b) => a.left - b.left);
  }
  // ── Tab Tổng quan
  // 7.17.4-thu.4: thẻ "Ngưỡng chỉ số": hộ thể và kháng tâm ma hiện tại so với mốc bắt đầu bị nén của game (dò số từ chính guardCurve / demonResistCurve). Chỉ hiển thị.
  function nguongChiSoHtml(nv) {
    try {
      const K = S.core, X = statCapCtx(nv), R = K.tinhKinhMach(nv, C()), e = statEff(X, R), body = kmIsBody(R);
      if (!X.gc && !X.dc) return '';
      const nguong = (fn) => { let lo = 0; for (let v = 0.01; v <= 3; v += 0.01) { let o; try { o = fn(v); } catch (err) { return null; } if (!Number.isFinite(o)) return null; if (o < v - 1e-6) return lo; lo = v; } return lo; };
      const dong = (ten, v, eff, nx) => {
        if (nx == null) return '';
        let kq;
        if (v <= nx + 1e-9) kq = `còn <b>${pct(Math.max(0, nx - v), 1)}</b> thì bắt đầu giảm hiệu quả`;
        else { const ratio = (eff - nx) / (v - nx); kq = `<span class="vk-bad">đã vượt ${pct(v - nx, 1)}</span>, phần vượt chỉ được ~${Math.round(Math.max(0, ratio) * 100)}%`; }
        return `<div class="vk-row"><span>${ten}</span><b style="text-align:right">${pct(v, 1)} <span class="vk-mu">(hiệu dụng ${pct(eff, 1)}, mốc nén ${pct(nx, 1)})</span></b></div><div class="vk-mu" style="font-size:12px;margin:-2px 0 6px">${kq}</div>`;
      };
      let h = '';
      if (X.gc) h += dong('Hộ Thể', e.ht, e.htEff, nguong((v) => X.gc(v, body, X.htTran, X.htNguong)));
      if (X.dc) h += dong('Kháng Tâm Ma', e.kt, e.ktEff, nguong((v) => X.dc(v)));
      if (!h) return '';
      return `<div class="vk-card"><h3>Ngưỡng chỉ số</h3>${h}<div class="vk-mu" style="font-size:12px">Tính theo kinh mạch đang xếp${body ? ' (thể tu)' : ''}. Khí huyết và Tốc Độ Tu Luyện game không nén theo mốc nên không liệt kê.</div></div>`;
    } catch (err) { return ''; }
  }
  // 8.6.2-thu.27: thẻ "Ý Cảnh" ở Tổng Quan: mọi ý cảnh đã tích, ý đang theo + buff, điểm tới bậc kế, Ngũ hành ý, dị anh, cách tích. Chỉ đọc, số lấy sống từ balance/intent.
  function yCanhHtml(nv) {
    try {
      const K = S.core;
      if (!K.intentPointsOf) return '';
      const pts = (k) => { try { return Math.max(0, Number(K.intentPointsOf(nv, k)) || 0); } catch (e) { return 0; } };
      const TEN0 = { kiem: 'Kiếm ý', sat: 'Sát ý', tu_bi: 'Từ bi' };
      const ten = (k) => { try { if (K.intentName) { const t = K.intentName(k); if (t) return String(t); } } catch (e) {} return TEN0[k] || (k === 'ngu_hanh' ? 'Ngũ hành ý' : k === 'vo_sac' ? 'Hư vô ý' : heTen(k) + ' ý'); };
      const bacTen = (t) => { try { return K.intentTierName ? String(K.intentTierName(t) || '') : ''; } catch (e) { return ''; } };
      const mocs = Array.isArray(K.INTENT_TIER_POINTS) ? K.INTENT_TIER_POINTS : [];
      const bacCua = (p) => { try { if (K.intentTier) return K.intentTier(p); } catch (e) {} let t = 0; for (const m of mocs) if (p >= m) t++; return t; };
      const keys = Array.isArray(K.INTENT_KEYS) && K.INTENT_KEYS.length ? K.INTENT_KEYS.slice() : ['kim', 'moc', 'thuy', 'hoa', 'tho', 'loi', 'bang', 'phong', 'am', 'vo_sac', 'kiem', 'sat', 'tu_bi'];
      const rows = keys.map((k) => ({ k, p: pts(k) }));
      const co = rows.filter((r) => r.p > 0).sort((a, b) => b.p - a.p), chua = rows.filter((r) => r.p <= 0);
      const minR = Number(K.INTENT_MIN_REALM) || 3, hien = (Number(nv.canhGioi) || 0) >= minR;
      let h = '';
      // dòng đầu: ý cảnh đang theo
      let main = null; try { main = K.mainIntentOf ? K.mainIntentOf(nv) : null; } catch (e) {}
      if (main) {
        const mt = main === 'ngu_hanh' ? Math.round(Number(K.fiveElementTier ? K.fiveElementTier(nv) : 0)) : bacCua(pts(main));
        let act = null; try { act = K.activeIntent ? K.activeIntent(nv) : null; } catch (e) {}
        h += '<div class="vk-row"><span>Đang theo</span><b>' + esc(ten(main)) + ' · bậc ' + mt + (bacTen(mt) ? ' (' + esc(bacTen(mt)) + ')' : '') + '</b></div>';
        let st;
        if (act) { let bt = ''; try { bt = K.intentBuffText ? String(K.intentBuffText(act.key, act.tier) || '') : ''; } catch (e) {} st = '<span class="vk-ok">Đang có buff</span>' + (bt ? ': ' + esc(bt) : ''); }
        else if (!hien) st = 'Tích ngầm, hiện ra khi lên Kết Đan.';
        else st = 'Chưa có buff (chưa đạt bậc Sơ hiện).';
        h += '<div class="vk-mu" style="font-size:12px;margin:-2px 0 6px">' + st + '</div>';
      } else h += '<div class="vk-mu" style="font-size:12px">Chưa có ý cảnh nào. ' + (hien ? '' : 'Dưới Kết Đan chỉ tích ngầm. ') + 'Đánh thắng trận bằng chiêu có hệ để bắt đầu tích.</div>';
      // bảng ý cảnh có điểm
      if (co.length) {
        h += '<table class="vk-t"><tr><th>Ý cảnh</th><th>Điểm</th><th>Bậc</th><th>Tới bậc kế</th></tr>' + co.map((r) => {
          const t = bacCua(r.p), nx = mocs.find((m) => m > r.p), pc = nx ? Math.min(100, r.p / nx * 100) : 100;
          return '<tr><td>' + esc(ten(r.k)) + (r.k === main ? ' <span class="vk-ok">●</span>' : '') + '</td><td>' + Math.round(r.p * 10) / 10 + '</td><td>' + t + (bacTen(t) ? ' ' + esc(bacTen(t)) : '') + '</td><td>'
            + (nx ? 'còn ' + Math.ceil(nx - r.p) + ' (mốc ' + nx + ')' : 'Viên mãn') + '<div style="height:4px;background:var(--line,#233);border-radius:2px;margin-top:2px"><i style="display:block;height:4px;width:' + pc.toFixed(0) + '%;background:var(--ok,#4c9);border-radius:2px"></i></div></td></tr>';
        }).join('') + '</table>';
      }
      if (chua.length) h += '<div class="vk-mu" style="font-size:12px;margin-top:4px">Chưa có: ' + chua.map((r) => esc(ten(r.k))).join(', ') + '.</div>';
      // Ngũ hành ý
      try {
        if (K.hasFiveIntent && K.fiveWeakest && K.hasFiveIntent(nv)) {
          const w = K.fiveWeakest(nv), bac = K.fiveElementTier ? K.fiveElementTier(nv) : (K.fiveHeTier ? K.fiveHeTier(w.points) : null);
          const fk = Array.isArray(K.INTENT_FIVE_KEYS) && K.INTENT_FIVE_KEYS.length ? K.INTENT_FIVE_KEYS : ['kim', 'moc', 'thuy', 'hoa', 'tho'];
          const ds = fk.map((x) => heTen(x) + ' ' + Math.round(pts(x))).join(' · ');
          const fm = Array.isArray(K.INTENT_FIVE_TIER_POINTS) ? K.INTENT_FIVE_TIER_POINTS : [];
          const fnx = fm.find((m) => m > w.points);
          h += '<div class="vk-row" style="margin-top:6px"><span>Ngũ hành ý</span><b>Bậc ' + (bac != null ? bac + (bacTen(bac) ? ' (' + esc(bacTen(bac)) + ')' : '') : '?') + ' · hệ yếu nhất ' + esc(heTen(w.key)) + ' (' + Math.round(w.points) + ' điểm)</b></div>'
            + '<div class="vk-mu" style="font-size:12px">Bậc Ngũ hành ý bằng bậc của hệ yếu nhất, nên luyện thêm hệ <b>' + esc(heTen(w.key)) + '</b> mới nâng được' + (fnx ? ' (còn ' + Math.ceil(fnx - w.points) + ' điểm tới mốc ' + fnx + ')' : '') + '. Điểm từng hệ: ' + ds + (fm.length ? '. Mốc mỗi hệ: ' + fm.join(' / ') : '') + '.</div>';
        }
      } catch (e) {}
      // dị anh + tên ý cảnh trong phẩm Hóa Thần (dạng phụ)
      try {
        const heYC = (d) => (d === 'kiem' ? 'Kiếm ý (chiêu từ mảnh kiếm, theo cách Kiếm ý tính; chưa kiểm)' : 'chiêu hệ ' + heTen(d));
        const uyDa = Number(K.UY_DI_ANH) || 0, uyTxt = uyDa > 0 ? ' uy ×' + String(Math.round(uyDa * 100) / 100).replace('.', ',') + ' (+' + Math.round((uyDa - 1) * 100) + '%)' : '';
        const diTen = (d) => { try { return K.DI_TUONG && K.DI_TUONG[d] ? String(K.DI_TUONG[d]) : (d === 'kiem' ? 'kiếm anh' : heTen(d) + ' anh'); } catch (e) { return String(d); } };
        const cg = Number(nv.canhGioi) || 0;
        if (nv.diTuong) {
          h += '<div class="vk-row" style="margin-top:6px"><span>Dị anh</span><b>' + esc(diTen(nv.diTuong)) + '</b></div><div class="vk-mu" style="font-size:12px">' + esc(heYC(nv.diTuong)) + esc(uyTxt) + '.' + (main && main !== 'ngu_hanh' && main !== nv.diTuong ? ' Ý cảnh đang theo khác hệ dị anh: buff ý cảnh và dị anh tăng hai hệ khác nhau.' : '') + '</div>';
        } else if (cg < 4 && K.pickDiTuong) {
          const d = K.pickDiTuong(nv);
          if (d) h += '<div class="vk-mu" style="font-size:12px;margin-top:6px">Lên Nguyên Anh lúc này sẽ ra <b>' + esc(diTen(d)) + '</b> (' + esc(heYC(d)) + esc(uyTxt) + '). Dị anh chốt theo ý cảnh đang theo lúc đột phá, sau đó không đổi.</div>';
        }
        if (K.intentLabelForGrade) { const l = K.intentLabelForGrade(nv); if (l) h += '<div class="vk-mu" style="font-size:12px;margin-top:6px">Tên ý cảnh trong phẩm Hóa Thần (chỉ là tên, đọc theo ý cảnh đang theo): <b>' + esc(String(l)) + '</b>.</div>'; }
      } catch (e) {}
      // cách tích, số đọc sống
      const sn = (x) => Number.isFinite(Number(x)) ? Number(x) : '?';
      const cach = [];
      cach.push('Thắng trận: chiêu ra nhiều nhất cho ' + (K.INTENT_WIN_POINTS != null ? sn(K.INTENT_WIN_POINTS) + ' điểm' : 'điểm') + ' cho hệ của chiêu (chiêu từ mảnh kiếm cho Kiếm ý)' + (K.INTENT_WINS_PER_YEAR != null ? ', tối đa ' + sn(K.INTENT_WINS_PER_YEAR) + ' trận tính điểm mỗi năm' : ''));
      if (K.INTENT_YEAR_POINTS != null) cach.push('Mỗi năm tu luyện / bế quan: ' + sn(K.INTENT_YEAR_POINTS) + ' điểm cho hệ chủ đạo của lưới (Từ bi khi tâm ma sạch, đạo tâm đủ)');
      if (K.INTENT_KILL_NAMED != null) cach.push('Giết người có tên: ' + sn(K.INTENT_KILL_NAMED) + ' điểm Sát ý' + (K.INTENT_EXECUTE_POINTS != null && K.INTENT_SPARE_POINTS != null ? '; xử trí sau trận: giết +' + sn(K.INTENT_EXECUTE_POINTS) + ' Sát, tha +' + sn(K.INTENT_SPARE_POINTS) + ' Từ bi' : ''));
      let mb = ''; try { if (K.mercyBuff) { const m = K.mercyBuff(nv); if (m && (m.demonResist || m.hp)) mb = 'Từ bi hiện cho kháng tâm ma +' + pct(m.demonResist || 0, 1) + ', khí huyết tối đa +' + pct(m.hp || 0, 1) + '.'; } } catch (e) {}
      h += '<details style="margin-top:6px"><summary>Cách tích điểm</summary><ul style="margin:4px 0 0;padding-left:18px;font-size:12px">' + cach.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>' + (mb ? '<div class="vk-mu" style="font-size:12px">' + esc(mb) + '</div>' : '') + '</details>';
      return '<details class="vk-card"' + (co.length ? ' open' : '') + '><summary><b>Ý Cảnh</b>' + (co.length ? ' <span class="vk-mu">· ' + co.length + ' ý cảnh có điểm</span>' : '') + '</summary>' + h + '</details>';
    } catch (e) { return ''; }
  }
  function tabTongQuan() {
    const K = S.core, c = ctx(), run = c.run, nv = run.nhanVat;
    const tho = K.thoNguyenToiDa(nv);
    const lc = nv.linhCan ? `${({ thien: 'Thiên', bien_di: 'Biến dị', song: 'Song', tap: 'Tạp', vo: 'Vô', ngu_hanh: 'Ngũ Hành' })[nv.linhCan.pham] || nv.linhCan.pham} linh căn (${(nv.linhCan.he || []).map(heTen).join(', ')})` : '—';
    let sect = '<div class="vk-mu">Chưa vào tông môn.</div>';
    const tm = K.tongMonCua(c);
    if (tm) {
      let ten = tm.slot; try { ten = c.world.info(tm.slot).diaDanh.ten; } catch {}
      const reasons = K.thieuDeThangCap(c);
      const next = K.CAP_BAC[tm.capBac + 1];
      sect = `<div class="vk-row"><span>Tông môn</span><b>${esc(ten)}</b></div>
      <div class="vk-row"><span>Cấp bậc</span><b>${esc(K.CAP_BAC[tm.capBac])}</b></div>
      <div class="vk-row"><span>Công tích</span><b>${Math.floor(tm.congTich)}</b></div>
      ${next ? `<div class="vk-row"><span>Lên ${esc(next)}</span>${reasons.length ? `<span class="vk-bad">${esc(reasons.join('; '))}</span>` : '<span class="vk-ok">Đủ điều kiện xin khảo hạch — xem tab Trận</span>'}</div>` : ''}`;
    }
    const nghe = Object.entries(nv.nghe || {}).map(([k, v]) => `${({ luyen_dan: 'Luyện đan', che_phu: 'Chế phù', luyen_bao: 'Luyện bảo', tran_phap: 'Trận pháp' })[k] || k}: bậc ${v.bac}, ${Math.floor(v.kinhNghiem)} kinh nghiệm`).join('<br>') || '—';
    // cơ duyên sắp hết hạn
    const dip = coDuyenConHan(c).filter((x) => x.left >= 0.05).map((x) => `<div class="vk-row"><span>${esc(x.ten)}</span><b>${num(x.left)} năm</b></div>${x.slot ? `<div class="vk-map-btns" style="display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap;margin:-2px 0 6px">${ddQuickTravelButton(x.slot, run.viTri, 'Đi tới')}${ddGuideButton(x.slot, run.viTri, 'Chỉ dẫn')}</div>` : ''}`).join('') || '<div class="vk-mu">Không có.</div>';
    body.innerHTML = `
    <div class="vk-card"><h3>${esc(nv.ten)}</h3>
      <div class="vk-row"><span>Cảnh giới</span><b>${esc(realmLabel(nv.canhGioi, nv.tieuCanhGioi))}</b></div>
      <div class="vk-row"><span>Tuổi / thọ</span><b>${Math.floor(nv.tuoi)} / ${tho} <span class="vk-mu">(còn ${Math.floor(tho - nv.tuoi)} năm)</span></b></div>
      <div class="vk-row"><span>Linh căn</span><b>${esc(lc)}</b></div>
      <div class="vk-row"><span>Thương thế</span><b>${nv.thuongThe ? `<span class="vk-bad">${nv.thuongThe} bậc</span>` : 'Lành lặn'}</b></div>
      <div class="vk-row"><span>Lịch luyện</span><b>${num(nv.lichLuyen || 0)}${(nv.lichLuyen || 0) < 2 ? ' <span class="vk-bad">sắp cạn — đi đánh/đi xa để hồi</span>' : ''}</b></div>
      <div class="vk-row"><span>Linh thạch · Cống hiến</span><b>${Math.floor(nv.linhThach || 0)} · ${Math.floor(nv.congHien || 0)}</b></div>
      <div class="vk-row"><span>Nghề</span><b style="text-align:right">${nghe}</b></div>
      <div class="vk-row"><span>Lượt khai thông kinh mạch</span><b>${(nv.kinhMach.cho && nv.kinhMach.cho.mo) || 0}</b></div>
    </div>
    ${yCanhHtml(nv)}
    <div class="vk-card"><h3>Sư môn</h3>${sect}</div>
    <div class="vk-card"><h3>Cơ duyên sắp hết hạn</h3>${dip}<div id="vk-guide"></div></div>
    <div class="vk-card"><h3>Độ mạnh chung</h3><div id="vk-dm" class="vk-mu">Bấm để đánh thử với mọi loại quái cùng cảnh giới.</div><button class="vk-btn" id="vk-dmb">Đánh thử</button></div>
    ${nguongChiSoHtml(nv)}
    ${tayTuyHtml(nv)}
    <div class="vk-mu" style="font-size:12px;text-align:center">Tool ${TOOL_VER} · game ${esc(K.bundle)}</div>`;
    ddBindQuickTravel(body);
    body.querySelectorAll('[data-vk-guide]').forEach((btn) => { btn.onclick = (ev) => { ev.preventDefault(); ev.stopPropagation(); bdShowGuide(body, btn.dataset.vkGuide); }; });
    body.querySelector('#vk-dmb').onclick = async (ev) => {
      ev.target.disabled = true; const out = body.querySelector('#vk-dm'); out.textContent = 'Đang đánh thử…'; await sleep0();
      const P = K.taoBenTa(nvNow(), C()); const res = [];
      for (const tc of [0, 1, 2, 3]) {
        let w = 0, n = 0;
        for (const def of C().enemies.values()) { let E; try { E = enemyAt(def, nv.canhGioi, tc); } catch { continue; } n++; if (fight(P, E).thang) w++; }
        res.push(`<div class="vk-row"><span>Quái ${esc(realmName(nv.canhGioi))} ${STAGE_DU[tc]}</span><b>thắng ${w}/${n} (${pct(w / Math.max(1, n))})</b></div>`); out.innerHTML = res.join(''); await sleep0();
      }
      if (nv.canhGioi < REALM_TEN.length - 1) {
        let w = 0, n = 0;
        for (const def of C().enemies.values()) { let E; try { E = enemyAt(def, nv.canhGioi + 1, 0); } catch { continue; } n++; if (fight(P, E).thang) w++; }
        res.push(`<div class="vk-row"><span>Quái ${esc(realmName(nv.canhGioi + 1))} Sơ Kỳ</span><b>thắng ${w}/${n} (${pct(w / Math.max(1, n))})</b></div>`);
      }
      out.innerHTML = res.join('') + '<div class="vk-mu" style="font-size:12px">Tính với kinh mạch đang xếp trong game.</div>';
    };
  }


