  function wiManh(nv) { const Kc = S.core, Cc2 = C(), g2 = Kc.luoiKinhMach(Cc2, nv); return nv.kinhMach.manh.map((m) => ({ m, key: m.item + ':' + m.x + ',' + m.y + ',' + m.xoay, cells: Kc.oCuaManh(g2, m, Cc2.items.get(m.item)) || [] })); }
