      out.push(['Số món · ô phủ / ô đang thông', Number.isFinite(x.mo) ? x.nMon + ' · ' + x.phu + ' / ' + x.mo : '—', Number.isFinite(y.mo) ? y.nMon + ' · ' + y.phu + ' / ' + y.mo : '—']);
