    const tuPills = nhoC('tuPills|' + nv.canhGioi, () => [...Cc.items.values()].filter((it) => it.tu_luyen && (it.tu_luyen.canh_gioi === undefined || it.tu_luyen.canh_gioi === nv.canhGioi)));
