    const cells = (m) => { const o = VKX_DO[m.id], p = ph(); return nenTat(m.id) ? ['—', '—', '—'] : o ? [f1(o.lan / p), f1(o.ms / p), f1(o.max)] : ['0', '0', '0']; };
    const dsTat = () => new Set(nenDocTat());
