      el.querySelector('#nen-nhe').onclick = () => { luu(new Set(VKX_NEN.filter((m) => m.nhe).map((m) => m.id))); ve(); };
      el.querySelector('#nen-het').onclick = () => { luu(new Set()); ve(); };
