  const phTen = (p) => (p ? (PHAM_TEN[p - 1] ? PHAM_TEN[p - 1] + ' Phẩm' : 'Phẩm ' + p) : '');
  const phNgan = (p) => (p ? (p === 8 ? 'Nghịch' : PHAM_TEN[p - 1] || 'P' + p) : '');
  const DIHOA_PCT = [0, 0, 6, 8, 10, 12, 15, 20];

