    const topHe = (arr) => { const m = {}; arr.forEach((it) => (it.he || []).forEach((h) => { if (h !== 'vo_sac') m[h] = (m[h] || 0) + 1; })); return Object.entries(m).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, 2).filter(([, n], i) => i === 0 || n >= arr.length * 0.2).map((x) => x[0]); };
