    den = Math.max(cur, Math.min(5, den | 0));
    try { hbScanBuilds(); } catch (e) { /* dùng danh sách tĩnh */ }
    const b = kbBuild(cfg.kb) || null, N = den - cur + 1, iters = Math.max(600, Math.round((cfg.iters || 3000) / 2));
    const bag = nvReal.tuiDo || {}, placed0 = (nvReal.kinhMach.manh || []).map((m) => ({ item: m.item, x: m.x, y: m.y, xoay: m.xoay }));
    const tenOf = (id) => { const it = c.items.get(id); return it ? it.ten : id; };
    const steps = []; let prev = placed0, aborted = false;
