        if (LT.stop) { aborted = true; break; }
        const sub = (f, label) => pg((k + Math.min(1, f || 0)) / N, realmName(R) + ' (' + (k + 1) + '/' + N + '): ' + (label || ''));
        sub(0, 'chọn món…'); await sleep0();
        const F = { R, st: 3, he: '', vo: true, dt: '', src: 'game', assume: true, phMin: 1, phMax: 8, heSet: b && b.mix ? b.elems : null, k: b ? b.k : '' };
