        const best = r.best, manh = best.manh.map((m) => ({ item: m.item, x: m.x, y: m.y, xoay: m.xoay })), prevSet = new Set(prev.map((m) => m.item)), idSet = new Set(manh.map((m) => m.item));
        let grid = '', tom = ''; try { grid = drawGrid(nv, manh); } catch (e) { grid = ''; } try { tom = boTomTat(nvReal, best.R); } catch (e) { tom = ''; }
