        let ln = ''; if (x.ln) { const y = x.ln.y, m = x.ln.m; if (m <= 0) ln = 'lắp mới: hệ số 0,5, thuần thục sau ' + (y == null ? '? năm' : '~' + num(y, y < 1 ? 2 : 1) + ' năm'); else if (m < 1) ln = 'đang lĩnh ngộ ' + pct(m) + (y == null ? '' : ', còn ~' + num(Math.max(0, (1 - m) * y), 1) + ' năm'); }
