        d.innerHTML = lc.parts.length ? lc.parts.map((p) => '<span' + (p.loi < 0 ? ' style="color:#a3322a"' : '') + '>' + esc(p.t) + '</span>').join(', ') + (lc.them ? ' <span style="opacity:.7">+' + lc.them + '</span>' : '') : '<span style="opacity:.7">không thưởng phạt</span>';
