  function auGiaiRange(cfg) { let lo = Math.floor(Number(cfg && cfg.giaiTu)), hi = Math.floor(Number(cfg && cfg.giaiDen)); if (!Number.isFinite(lo)) lo = 0; if (!Number.isFinite(hi)) hi = 5; lo = Math.max(0, Math.min(5, lo)); hi = Math.max(0, Math.min(5, hi)); return lo <= hi ? [lo, hi] : [hi, lo]; }
  const auGiaiFull = (cfg) => { const r = auGiaiRange(cfg); return r[0] === 0 && r[1] === 5; };
  function auGiaiRangeLabel(cfg) { const [lo, hi] = auGiaiRange(cfg); return lo === 0 && hi === 5 ? 'mọi giai' : lo === hi ? auGiaiLabel(lo) : AU_GIAI_TEN[lo] + ' → ' + AU_GIAI_TEN[hi]; }
  function auGiaiOf(c, slot) { try { const v = Number(c.world.info(slot).capNen); return Number.isFinite(v) ? Math.max(0, Math.min(5, Math.floor(v))) : null; } catch (e) { return null; } }
