  function auMucBad(tran, mucs) { const bad = new Set(); for (const d of (tran && tran.dich) || []) { const k = auMucKey(d && d.muc); if (!mucs.includes(k)) bad.add(k); } if (tran && tran.muc) { const k = auMucKey(tran.muc); if (!mucs.includes(k)) bad.add(k); } return [...bad]; } // 7.13.0-thu.3: xét cả mức ép của sự kiện (tran.muc)
