      if (!chip) { const sb = UI.win.querySelector('.vkx-subbar'); if (sb) { chip = document.createElement('div'); chip.id = 'vkx-auchip'; chip.style.cssText = 'display:none;font-size:11px;padding:2px 0;cursor:pointer;opacity:.85'; chip.onclick = () => { const dd = auBarDs(), t = (dd.walk || dd.nen[0] || {}).tab; if (t) goTab(t); }; sb.appendChild(chip); } }
      if (chip) { chip.style.display = co ? 'block' : 'none'; chip.textContent = co ? 'Auto: ' + (d.walk ? d.walk.ten : 'không đi lại') + (d.nen.length ? ' · nền ' + d.nen.length : '') : ''; }
