    const warn = (m) => { if (cfg.cach === 'nl') { st.bad.add(run.viTri); auLog('Săn nguyên liệu: ' + m + ', bỏ nơi này.', 'vk-warn'); return 'skip'; } if (!st.truyWarn) { st.truyWarn = true; auLog('Truy Tìm Đích Danh: ' + m + ' → săn ngẫu nhiên.', 'vk-warn'); } return null; };
