      if (reasons.debuff && !reasons.mau) { st.bad.add(run.viTri); auLog('Truy Tìm Đích Danh: mọi loài ở ' + placeName(ctxLite(), run.viTri) + ' đều dính debuff khi bị giết, bỏ nơi này.', 'vk-warn'); return 'skip'; }
