  function dgStatus(st) {
    if (!st || st.kind !== 'dg') return '<div class="vk-mu" style="font-size:13px">Chưa chạy.</div>';
    const run = G() && G().state.run, nv = run ? run.nhanVat : null;
    const rows = [['Trạng Thái', st.running ? '<span class="vk-ok">Đang chạy…</span>' : 'Đã dừng'], ['Lý Do Dừng', st.running ? '—' : esc(st.msg || '—')], ['Nhà Đấu Giá', esc(st.house ? st.house.ten : '—')], ['Đã Đoạt', st.won], ['Lần Ra Giá', st.bids], ['Lô Bỏ Qua', st.passes], ['Lần Đợi Kỳ Mới', st.cycles]];
    if (nv && run) { rows.push(['Năm Đã Trôi', num(run.nam - st.nam0)]); rows.push(['Linh Thạch Thay Đổi', (Math.floor(nv.linhThach) - st.lt0 >= 0 ? '+' : '') + (Math.floor(nv.linhThach) - st.lt0)]); rows.push(['Thọ Nguyên Còn', Math.floor(auLifeLeft()) + ' năm']); }
    return rows.map((r) => `<div class="vk-row"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('');
  }
  // Giá khởi điểm ƯỚC của một món: lô cố định (AuctionLotDef.gia, không có thì gia của vật), hoặc gia của vật x he_so_gia của kệ đấu giá cùng loại; lấy thấp nhất trong các nhà đã quét.
  function dgGiaUoc(itemId) {
    const it = C().items.get(itemId); if (!it || !Array.isArray(DG.res)) return null;
    let best = null; const hat = (v) => { if (v > 0 && (best === null || v < best)) best = v; };
    for (const h of DG.res) {
      const ad = h.def && h.def.dau_gia; if (!ad) continue;
      for (const l of ad.lo || []) if (l.id === itemId) hat(l.gia ?? it.gia ?? 0);
      for (const sh of ad.ke || []) if (sh.loai === it.loai) hat(Math.round((it.gia || 0) * (sh.he_so_gia || 1)));
    }
    return best;
  }
