    const sum = tcs.reduce((s, t) => s + t.tl, 0) || 1, tmo = rrTmCo() ? rrTmOpts() : { nuoc: [], xt: [] }, tlt = rrTmCo() ? rrTmLcTc() : { lc: null, tc: null }, tq = rrTmCo() ? rrTmQuyen() : {};
    const row = (lab, ctl) => `<label style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin:5px 0;font-size:13px"><span>${lab}</span>${ctl}</label>`;
    const sel = (id, lab, opts, v, dis) => row(lab + (dis ? ' <span class="vk-mu" style="font-size:11px">(chưa khắc)</span>' : ''), `<select class="vk-sel" id="${id}" style="width:200px"${dis ? ' disabled' : ''}>${opts.map(([k, t]) => `<option value="${esc(k)}" ${!dis && String(v) === String(k) ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select>`);
