    h += khoi('Nhà đấu giá gần đây (danh mục xem khi vào)', (X.dg || []).map((r) => ({ slot: r.slot, y: r.y, nhan: r.ten, html: `<b>${esc(r.ten)}</b> ở ${esc(placeName(c, r.slot))}<br><span class="vk-mu" style="font-size:12px">${r.nam != null ? 'đổi danh mục năm ' + esc(String(Math.round(r.nam))) + ' · ' : ''}${r.xs != null ? '~' + dgPct(r.xs) + ' mỗi kỳ có món này (ước lượng từ dữ liệu game, mỗi kỳ rút ngẫu nhiên nên không chắc) · ' : ''}danh mục xem khi vào, không tra trước được</span>` })));
