        const def = C().encounters.get(r.id); if (!def) return '';
        con = auOffersSan(auShopCtx(c, r.slot, sang - nam, r.id), r.slot, r.id, def).some((x) => x.itemId === r.itemId && !x.het);
        if (TD_MOC.size > 300) TD_MOC.clear(); TD_MOC.set(key, con);
