      const thang = Math.min(12, Math.floor((den - Math.floor(den)) * 12) + 1);
      return 'sát mốc năm: tới nơi khoảng tháng ' + thang + ' năm ' + Math.floor(den) + ', sang năm ' + sang + ' kệ đổi và món này không còn, phải tới trước tháng 1 năm ' + sang;
