          var hidden = !!def.an, name, glyph, color = KCOL[kind] || KCOL.su_kien;
          var soiAn = false; if (hidden) { try { soiAn = !!(UI.qtSoi && UI.qtSoi()); } catch (e) { soiAn = false; } } // 8.6.2-thu.15
          if (hidden) { color = COL_HIDDEN; }
